-- +goose Up
-- Each tenant table's tenant_isolation policy shows a row only when its
-- livemode matches the transaction's app.livemode setting. It read an unset
-- setting as live. It now matches 'on' to live rows and 'off' to test rows,
-- and an unset or empty setting matches no row, so nothing reads as live
-- unless it says so. The bypass branch is unchanged. A policy cannot raise
-- an error the way the insert trigger does (00213): Postgres may evaluate
-- the mode check even when app.bypass_rls is 'on'.
ALTER POLICY tenant_isolation ON public.api_keys USING (((current_setting('app.bypass_rls', true) = 'on') OR ((tenant_id = current_setting('app.tenant_id', true)) AND (livemode = CASE current_setting('app.livemode', true) WHEN 'on' THEN true WHEN 'off' THEN false END))));
